#!/usr/bin/env bash
# Generates the cloudflare-proxied-networks ConfigMap: trusted proxy CIDRs (VPS + Cloudflare)
# in several formats. The core Flux Kustomization expands SECRET_VPS_IPS (comma-separated);
# apps read the keys through postBuild.substituteFrom.

set -euo pipefail

# Get all cloudflare ipv4 and ipv6 ranges in an array
cloudflare="$(
    { curl -fsSL https://www.cloudflare.com/ips-v4; echo; curl -fsSL https://www.cloudflare.com/ips-v6; } \
    | jq --raw-input --slurp 'split("\n") | map(select(. != ""))'
)"
if [[ "$(jq length <<< "${cloudflare}")" -eq 0 ]]; then
    exit 1
fi

list="$(jq --raw-output 'join(", ")' <<< "${cloudflare}")"
csv="$(jq --raw-output 'join(",")' <<< "${cloudflare}")"
helm="$(jq --raw-output 'join("\\,")' <<< "${cloudflare}")"

cat <<YAML
---
# Generated by .github/scripts/cloudflare-proxied-networks.sh, do not edit.
# Source of truth: SECRET_VPS_IPS + https://www.cloudflare.com/ips/
apiVersion: v1
kind: ConfigMap
metadata:
  name: cloudflare-proxied-networks
  namespace: flux-system
data:
  # YAML flow list, use as a whole value: "trustedIPs: <var>"
  CLOUDFLARE_PROXIED_NETWORKS: '[\${SECRET_VPS_IPS}, ${list}]'
  # Comma-separated
  CLOUDFLARE_PROXIED_NETWORKS_CSV: '\${SECRET_VPS_IPS},${csv}'
  # Escaped commas for Helm --set / HelmRelease valuesFrom targetPath
  CLOUDFLARE_PROXIED_NETWORKS_HELM: '\${SECRET_VPS_IPS//,/\\\\,}\\,${helm}'
YAML
